parameters.jsCode:
// Get OpenAI response item (usually single)
const openaiItem = $input.all()[0].json;

// Extract text content safely
let text = "";

if (openaiItem.choices?.[0]?.message?.content) {
  text = openaiItem.choices[0].message.content;
} else if (openaiItem.choices?.[0]?.text) {
  text = openaiItem.choices[0].text;
} else {
  text = JSON.stringify(openaiItem).slice(0, 1000);
}

// 🧹 Remove markdown fences if present (```json ... ```)
text = text.replace(/^```json\s*/i, "").replace(/```$/i, "").trim();

// Parse JSON output safely
let result;
try {
  result = JSON.parse(text);
} catch (err) {
  result = {
    should_block: false,
    overall_score: 0,
    critical_issues: [],
    suggestions: ["Failed to parse JSON from LLM output."],
    summary: text.substring(0, 800)
  };
}

// 🧠 Extract PR metadata (passed through input chain)
const meta = openaiItem; // if metadata was merged into same object earlier

return [
  {
    json: {
      review: result,
      llm_raw: text,
      repo: $('github-pr-review').first().json.body.pull_request.head.repo.full_name || null,
      pr_number: $('github-pr-review').first().json.body.pull_request.number || null,
      head_sha: $('Get PR Files').first().json.sha || null
    }
  }
];

// Get review object from previous node
const input = $input.all()[0].json;
const r = input.review;

let lines = [];
lines.push("### 🤖 Automated Code Review\n");
lines.push(`**Summary:** ${r.summary || "No summary provided."}\n`);

if (r.critical_issues && r.critical_issues.length) {
  lines.push("**Critical Issues:**");
  for (let c of r.critical_issues) {
    lines.push(`- ${c.file || 'unknown'}:${c.line || '-'} — ${c.message}`);
  }
}

if (r.suggestions && r.suggestions.length) {
  lines.push("\n**Suggestions:**");
  for (let s of r.suggestions) {
    lines.push(`- ${s}`);
  }
}

return [
  {
    json: {
      body: lines.join("\n"),
      repo: $('github-pr-review').first().json.body.pull_request.head.repo.full_name,
      pr_number: $('github-pr-review').first().json.body.pull_request.number,
      head_sha: $('github-pr-review').first().json.body.pull_request.head.sha
    }
  }
];

const r = $json.review;
const summary = `Automated Code Review: Passed ✅. Calculated Score is: ${r.overall_score || 'N/A'}. Here is the Review Summary: ${r.summary || ''}`;
return [{ json: { body: summary } }];

