parameters.jsCode:
// Function node set to "Run Once for All Items"
const MAX_FILES = 6;
const MAX_CHARS_PER_DIFF = 4000;

// Get all PR files from previous node
let files = $input.all().map(i => i.json);
if (files.length > MAX_FILES) files = files.slice(0, MAX_FILES);

// Build the review prompt
let prompt =
"💡 **Context**: You are a *Senior Automation Architect* with deep expertise in Selenium (Java), TestNG, Page Object Model (POM), Log4j, and Extent Reports.\n" +
"Perform a **fresh, context-independent code review** of the provided Selenium test files. " +
"⚠️ Do NOT compare against any previous commits or diff context — instead, evaluate the code as if it is *entirely new*, using the following best practice guidelines.\n\n" +

"---\n" +
"### 🧭 Review Intent\n" +
"- Treat every code block as newly written. Do NOT reference or assume old code or deletions.\n" +
"- Focus solely on the *current implementation quality*, not historical changes.\n" +
"- Do NOT penalize removed code or renamed methods if the new version aligns with guidelines.\n" +
"---\n\n" +

"### 📘 Code Review Guidelines\n" +
"1. **Code Structure & Readability** – Enforce Java/Selenium coding standards, naming conventions, consistent indentation, and removal of redundant logic.\n" +
"2. **Page Object Model (POM)** – Ensure clear separation between locators, reusable methods, and test logic. Prefer explicit waits over Thread.sleep.\n" +
"3. **Selenium Best Practices** – Validate driver setup/teardown logic, WebDriverManager usage, and avoidance of hard-coded data.\n" +
"4. **TestNG Implementation** – Check use of annotations (@Test, @BeforeMethod, @AfterMethod), assertion logic, and grouping strategy.\n" +
"5. **Logging (Log4j)** – Ensure proper log levels (INFO, DEBUG, ERROR) and avoid exposing sensitive data.\n" +
"6. **Extent Reports Integration** – Validate report initialization, test log entries, screenshot capture, and final report flush.\n" +
"7. **Error Handling & Robustness** – Highlight missing try/catch, poor exception handling, and lack of recovery for flaky tests.\n" +
"8. **Framework Design & Scalability** – Assess modularity, package hierarchy (base/pages/tests/utils), and parallel test readiness.\n" +
"9. **Configuration Management** – Ensure all environment data and URLs are externalized, not hardcoded.\n" +
"10. **CI/CD & Maintainability** – Verify tests can run in headless mode, support parallel runs, and integrate with Jenkins or GitHub Actions.\n\n" +

"### ⚙️ Review Focus Areas\n" +
"1. Maintainability – No hard-coded waits; prefer explicit waits.\n" +
"2. Stability – Avoid timing-based or order-dependent tests.\n" +
"3. Reusability – Maximize reusable components and methods.\n" +
"4. Readability – Clear test names, concise assertions.\n" +
"5. Scalability – No duplicate locators; centralize selectors.\n" +
"6. Data Handling – Externalize configuration and test data.\n" +
"7. Error Handling – Proper try/catch with meaningful logs.\n" +
"8. Framework Standards – Follow naming, folder, and reporting conventions.\n" +
"9. Performance – Avoid unnecessary browser actions or sleeps.\n" +
"10. CI/CD Fit – Ensure compatibility with headless mode and parallel execution.\n\n" +

"### 🧾 Output Format\n" +
"Return ONLY valid JSON with these keys:\n" +
"- should_block: true/false (whether code violates critical standards)\n" +
"- overall_score: (0–100) based on code quality\n" +
"- critical_issues: array of {file, line, message}\n" +
"- suggestions: array of short actionable improvements\n" +
"- summary: a single concise paragraph summarizing your review\n\n" +

"---\n" +
"### PR Metadata\n" +
"PR Number: " + $('github-pr-review').first().json.body.pull_request.number +
"\nRepository: " + $('github-pr-review').first().json.body.pull_request.head.repo.full_name +
"\nHead SHA: " + $input.first().json.sha +
"\n\n" +
"---\n" +
"### 🔍 Files to Review (fresh evaluation)\n\n";

for (const f of files) {
    const filename = f.filename;
    const diff = (f.patch || '').substring(0, MAX_CHARS_PER_DIFF);
    prompt += `📄 FILE: ${filename}\n\nCODE:\n${diff}\n\n---\n\n`;
}

// Grab PR metadata
const first = files[0] || {};

return {
    json: {
        prompt,
        repo: first?.body?.repository?.name || '',
        pr_number: first?.body?.pull_request?.number || 0,
        head_sha: first?.body?.pull_request?.head?.sha || ''
    }
};

// Only continue if PR action is one of: opened, reopened, synchronize
if (!['opened', 'reopened', 'synchronize'].includes($input.first().json.body.action)){
  // Stop workflow execution for other actions
  return [];
}

// Pass item forward for processing
return $input.all();
